public class Main {
    static class Edge implements Comparable<Edge> {
        int u, v, w;

        Edge(int u, int v, int w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }

        public int compareTo(Edge other) {
            return Integer.compare(other.w, this.w);
        }
    }

    static int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static int query(int u, int v, int LOG, int[][] up, int[][] minW, int[] depth) {
        int ans = Integer.MAX_VALUE;

        if (depth[u] < depth[v]) {
            int tmp = u;
            u = v;
            v = tmp;
        }

        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++) {
            if ((diff & (1 << k)) != 0) {
                ans = Math.min(ans, minW[k][u]);
                u = up[k][u];
            }
        }

        if (u == v) return ans;

        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][u] != up[k][v]) {
                ans = Math.min(ans, minW[k][u]);
                ans = Math.min(ans, minW[k][v]);
                u = up[k][u];
                v = up[k][v];
            }
        }

        ans = Math.min(ans, minW[0][u]);
        ans = Math.min(ans, minW[0][v]);
        return ans;
    }

