        int[] parent = new int[N + 1];
        int[] size = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        int[] head = new int[N + 1];
        Arrays.fill(head, -1);

        int maxEdges = 2 * B + 5;
        int[] to = new int[maxEdges];
        int[] wt = new int[maxEdges];
        int[] nxt = new int[maxEdges];
        int idx = 0;

        for (Edge e : edges) {
            int ru = find(parent, e.u);
            int rv = find(parent, e.v);

            if (ru != rv) {
                if (size[ru] < size[rv]) {
                    parent[ru] = rv;
                    size[rv] += size[ru];
                } else {
                    parent[rv] = ru;
                    size[ru] += size[rv];
                }

                to[idx] = e.v;
                wt[idx] = e.w;
                nxt[idx] = head[e.u];
                head[e.u] = idx++;

                to[idx] = e.u;
                wt[idx] = e.w;
                nxt[idx] = head[e.v];
                head[e.v] = idx++;
            }
        }

        int LOG = 1;
        while ((1 << LOG) <= N) LOG++;

        int[][] up = new int[LOG][N + 1];
        int[][] minW = new int[LOG][N + 1];
        int[] depth = new int[N + 1];

        int[] stack = new int[N + 1];
        int top = 0;

        stack[top++] = 1;
        depth[1] = 0;
        up[0][1] = 1;
        minW[0][1] = Integer.MAX_VALUE;

        while (top > 0) {
            int u = stack[--top];

            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];

                if (v == up[0][u]) continue;

                up[0][v] = u;
                minW[0][v] = wt[e];
                depth[v] = depth[u] + 1;
                stack[top++] = v;
            }
        }

        for (int k = 1; k < LOG; k++) {
            for (int v = 1; v <= N; v++) {
                int mid = up[k - 1][v];
                up[k][v] = up[k - 1][mid];
                minW[k][v] = Math.min(minW[k - 1][v], minW[k - 1][mid]);
            }
        }

        st = new StringTokenizer(br.readLine());
        int C = Integer.parseInt(st.nextToken());

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < C; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());

            sb.append(query(x, y, LOG, up, minW, depth)).append('\n');
        }

        System.out.print(sb);
    }
}
